//! End-to-end: read the checked-in pcap savefile, classify, and render.
//!
//! The fixture is generated by `scripts/make-fixture.py` and contains Ethernet
//! frames for host↔remote, remote↔LAN-peer, LAN↔LAN, IPv6, ARP, and a
//! truncated frame.

use netscope::capture::Sample;
use netscope::capture::parse::{self, LinkLayer, Transport};
use netscope::model::Model;
use netscope::net::{LocalNetwork, Location};
use netscope::render::{Hud, Scene};
use pcap::Capture;
use std::net::IpAddr;
use std::time::Instant;

fn ip(s: &str) -> IpAddr {
    s.parse().unwrap()
}

/// Reads the fixture and returns (frames seen, frames decoded).
fn replay(network: &LocalNetwork, model: &mut Model) -> (u64, u64) {
    let mut cap = Capture::from_file("fixtures/sample.pcap").expect("fixture must exist");
    let link = LinkLayer::from_pcap_value(cap.get_datalink().0);
    assert_eq!(link, LinkLayer::Ethernet);

    let t0 = Instant::now();
    let mut seen = 0;
    let mut decoded = 0;
    while let Ok(packet) = cap.next_packet() {
        seen += 1;
        if let Some(frame) = parse::decode(link, packet.data) {
            decoded += 1;
            model.ingest(&Sample { frame }, network, t0);
        }
    }
    (seen, decoded)
}

#[test]
fn fixture_classifies_host_lan_and_remote_correctly() {
    let network =
        LocalNetwork::parse_overrides(&["eth0/192.168.1.20/24".to_string()]).expect("override");
    assert_eq!(network.subnets().len(), 1);

    let mut model = Model::default();
    let (seen, decoded) = replay(&network, &mut model);
    assert_eq!(seen, 9, "fixture has 9 packets");
    // ARP and the truncated frame are not IP, so 7 decode.
    assert_eq!(decoded, 7);

    // Only 192.168.1.0/24 is declared local here, so the fixture's second
    // interface address 10.20.0.5 counts as a remote endpoint.
    assert_eq!(model.remote_count(), 5);
    assert_eq!(model.lan_count(), 2);

    let remote_addrs: Vec<String> = model.remotes().map(|h| h.addr.to_string()).collect();
    assert!(remote_addrs.contains(&"10.20.0.5".to_string()));
    for expected in ["93.184.216.34", "10.5.5.5", "2001:db8::1", "2001:db8::2"] {
        assert!(
            remote_addrs.contains(&expected.to_string()),
            "missing {expected}"
        );
    }
    let lan_addrs: Vec<String> = model.lan().map(|h| h.addr.to_string()).collect();
    assert!(lan_addrs.contains(&"192.168.1.7".to_string()));
    assert!(lan_addrs.contains(&"192.168.1.9".to_string()));

    // The host's own address is never a remote or a LAN peer.
    assert_eq!(network.classify(ip("192.168.1.20")), Location::Host);
    assert!(!remote_addrs.contains(&"192.168.1.20".to_string()));

    // Both link kinds exist: some flows anchor on our interface, some on the LAN.
    let anchored_local = model
        .flows()
        .filter(|f| f.local == Some(ip("192.168.1.20")))
        .count();
    let anchored_lan = model.flows().filter(|f| f.local.is_none()).count();
    assert!(
        anchored_local >= 1,
        "expected a link to the middle interface"
    );
    assert!(
        anchored_lan >= 1,
        "expected a link to the local-network circle"
    );

    // LAN peer -> our interface produces an interface<->LAN-circle link.
    let lan_links: Vec<_> = model.lan_links().collect();
    assert_eq!(lan_links.len(), 1);
    assert_eq!(lan_links[0].peer, ip("192.168.1.7"));
    assert_eq!(lan_links[0].local, ip("192.168.1.20"));

    // The remote that talked to a LAN peer is flagged as such.
    let with_lan = model
        .remotes()
        .find(|h| h.addr == ip("10.5.5.5"))
        .expect("10.5.5.5");
    assert_eq!(with_lan.lan_packets, 1);
    assert_eq!(with_lan.last_transport, Transport::Udp);
}

#[test]
fn fixture_replay_renders_without_panicking() {
    let network =
        LocalNetwork::parse_overrides(&["eth0/192.168.1.20/24".to_string()]).expect("override");
    let mut model = Model::default();
    replay(&network, &mut model);

    let mut scene = Scene::new(1024, 768);
    let hud = Hud {
        source: "fixture",
        frames_seen: 8,
        frames_decoded: 6,
        remotes: model.remote_count(),
        lan_peers: model.lan_count(),
        quiet_for: 0.0,
        fps: 30.0,
        notice: Some("replay finished"),
    };
    let placed = scene.draw(&network, &model, &hud, Instant::now());

    // Every remote in the model should have been placed on the left half.
    assert_eq!(placed.remotes.len(), model.remote_count());
    let host = placed.host.as_ref().expect("host panel");
    assert!(placed.remotes.iter().all(|r| r.center.x < host.rect.x0));
}

#[test]
fn overrides_reject_malformed_specs() {
    assert!(LocalNetwork::parse_overrides(&[]).is_err());
    assert!(LocalNetwork::parse_overrides(&["nonsense".to_string()]).is_err());
    assert!(LocalNetwork::parse_overrides(&["/192.168.1.1/24".to_string()]).is_err());
    assert!(LocalNetwork::parse_overrides(&["eth0/not-an-ip/24".to_string()]).is_err());
    assert!(LocalNetwork::parse_overrides(&["eth0/192.168.1.1/99".to_string()]).is_err());
    // IPv6 addresses contain colons, not slashes, so they parse fine.
    let net = LocalNetwork::parse_overrides(&["eth0/2001:db8::1/48".to_string()]).expect("v6 ok");
    assert_eq!(net.subnets().len(), 1);
}
